namespace {
float number(jass::Real v){return std::bit_cast<float>(v.bits());}
jass::Real real(float v){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(v));}
int cell(float v){return int(std::clamp(std::floor(double(v)/512),double(INT_MIN),double(INT_MAX)));}
std::uint64_t key(int x,int y){return (std::uint64_t(std::uint32_t(x))<<32)|std::uint32_t(y);}
float distance(const UnitState& a,const UnitState& b){return std::hypot(number(a.x)-number(b.x),number(a.y)-number(b.y));}
}
